class Solution {
public:
    string boldWords(vector<string>& words, string s) {
        int n = s.length();
        vector<bool> bold(n, false);
        for (const string& word : words) {
            int wl = word.length();
            size_t pos = s.find(word, 0);
            while (pos != string::npos) {
                for (int i = 0; i < wl; i++) bold[pos + i] = true;
                pos = s.find(word, pos + 1);
            }
        }
        string res = "";
        for (int i = 0; i < n; i++) {
            if (bold[i] && (i == 0 || !bold[i - 1])) res += "<b>";
            res += s[i];
            if (bold[i] && (i == n - 1 || !bold[i + 1])) res += "</b>";
        }
        return res;
    }
};

class Solution {
    public String boldWords(String[] words, String s) {
        int n = s.length();
        boolean[] bold = new boolean[n];
        for (String word : words) {
            int wl = word.length();
            int idx = s.indexOf(word, 0);
            while (idx != -1) {
                for (int i = 0; i < wl; i++) bold[idx + i] = true;
                idx = s.indexOf(word, idx + 1);
            }
        }
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (bold[i] && (i == 0 || !bold[i - 1])) res.append("<b>");
            res.append(s.charAt(i));
            if (bold[i] && (i == n - 1 || !bold[i + 1])) res.append("</b>");
        }
        return res.toString();
    }
}

var boldWords = function(words, s) {
    const n = s.length;
    const bold = new Array(n).fill(false);
    for (const word of words) {
        let idx = s.indexOf(word, 0);
        while (idx !== -1) {
            for (let i = 0; i < word.length; i++) bold[idx + i] = true;
            idx = s.indexOf(word, idx + 1);
        }
    }
    const res = [];
    for (let i = 0; i < n; i++) {
        if (bold[i] && (i === 0 || !bold[i - 1])) res.push("<b>");
        res.push(s[i]);
        if (bold[i] && (i === n - 1 || !bold[i + 1])) res.push("</b>");
    }
    return res.join("");
};
